CREATE OR REPLACE PROCEDURE purge_old_audit_logs(p_retention_days INT)
LANGUAGE plpgsql AS $$
DECLARE
    v_deleted_count INT;
BEGIN
    LOOP
        DELETE FROM audit_logs
        WHERE id IN (
            SELECT id FROM audit_logs
            WHERE created_at < NOW() - (p_retention_days || ' days')::INTERVAL
            LIMIT 10000
        );
        GET DIAGNOSTICS v_deleted_count = ROW_COUNT;

        -- Commit batch to release locks and allow WAL cleanup
        COMMIT;

        EXIT WHEN v_deleted_count = 0;
    END LOOP;
END;
$$;

CREATE OR REPLACE PROCEDURE archive_old_orders(p_days int)
LANGUAGE plpgsql
AS $$
DECLARE
    batch_size constant int := 10000;
    moved      int;
BEGIN
    LOOP
        BEGIN
            WITH victims AS (
                SELECT id
                FROM orders
                WHERE ordered_at < now() - make_interval(days => p_days)
                LIMIT batch_size
            )
            DELETE FROM orders o
            USING victims v
            WHERE o.id = v.id;

            GET DIAGNOSTICS moved = ROW_COUNT;
            COMMIT;

            EXIT WHEN moved < batch_size;
        EXCEPTION WHEN others THEN
            ROLLBACK;
            RAISE NOTICE 'Batch failed, stopping: %', SQLERRM;
            EXIT;
        END;
    END LOOP;
END $$;

CALL archive_old_orders(365);
